import{_ as s,o as t,c as i,ag as n}from"./chunks/framework.DKalukzk.js";const m=JSON.parse('{"title":"Analyser la profession","description":"Comprendre les tâches, les compétences et les limites des postes en informatique","frontmatter":{"title":"Analyser la profession","description":"Comprendre les tâches, les compétences et les limites des postes en informatique"},"headers":[],"relativePath":"modules/04-analyse-info/03-profession.md","filePath":"modules/04-analyse-info/03-profession.md"}'),a={name:"modules/04-analyse-info/03-profession.md"};function o(l,e,r,p,u,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="analyser-la-profession" tabindex="-1">Analyser la profession <a class="header-anchor" href="#analyser-la-profession" aria-label="Permalink to &quot;Analyser la profession&quot;">​</a></h1><p>Dans le programme, on vous demande aussi d&#39;analyser la profession elle-même, pas seulement les entreprises.</p><h2 id="developpeur-d-application-un-point-de-depart-utile" tabindex="-1">Développeur d&#39;application : un point de départ utile <a class="header-anchor" href="#developpeur-d-application-un-point-de-depart-utile" aria-label="Permalink to &quot;Développeur d&#39;application : un point de départ utile&quot;">​</a></h2><p>Le poste de <strong>développeur d&#39;application</strong> est un bon point de repère pour comprendre plusieurs réalités du domaine.</p><p>On y retrouve souvent :</p><ul><li>l&#39;analyse des besoins</li><li>la programmation</li><li>les tests</li><li>la correction de problèmes</li><li>la maintenance et l&#39;amélioration d&#39;une application</li></ul><h2 id="taches-et-responsabilites" tabindex="-1">Tâches et responsabilités <a class="header-anchor" href="#taches-et-responsabilites" aria-label="Permalink to &quot;Tâches et responsabilités&quot;">​</a></h2><p>Quand vous analysez une profession, cherchez les tâches concrètes associées au poste.</p><p>Exemples :</p><ul><li>développer une fonctionnalité</li><li>corriger un bogue</li><li>tester une application</li><li>collaborer avec l&#39;équipe</li><li>documenter le travail effectué</li></ul><h2 id="connaissances-comportements-attitudes-et-habiletes" tabindex="-1">Connaissances, comportements, attitudes et habiletés <a class="header-anchor" href="#connaissances-comportements-attitudes-et-habiletes" aria-label="Permalink to &quot;Connaissances, comportements, attitudes et habiletés&quot;">​</a></h2><p>Pour exercer une profession en informatique, il ne suffit pas de connaître un langage de programmation.</p><p>Il faut aussi tenir compte de plusieurs éléments :</p><ul><li><strong>connaissances</strong> : notions techniques, outils, environnement de travail</li><li><strong>comportements</strong> : rigueur, autonomie, professionnalisme</li><li><strong>attitudes</strong> : curiosité, ouverture, capacité d&#39;adaptation</li><li><strong>habiletés</strong> : communication, analyse, résolution de problèmes, travail d&#39;équipe</li></ul><h2 id="limites-d-intervention-selon-les-postes" tabindex="-1">Limites d&#39;intervention selon les postes <a class="header-anchor" href="#limites-d-intervention-selon-les-postes" aria-label="Permalink to &quot;Limites d&#39;intervention selon les postes&quot;">​</a></h2><p>Tous les postes n&#39;ont pas la même portée.</p><p>Par exemple :</p><ul><li>un <strong>programmeur</strong> exécute surtout des tâches de développement précises</li><li>un <strong>analyste</strong> intervient davantage dans l&#39;analyse des besoins et la conception</li><li>un <strong>développeur d&#39;application</strong> peut occuper un rôle plus ou moins large selon l&#39;entreprise</li></ul><p>L&#39;important est de comprendre que les titres se ressemblent parfois, mais que les responsabilités peuvent varier.</p><h2 id="lien-avec-les-conferences-et-les-visites" tabindex="-1">Lien avec les conférences et les visites <a class="header-anchor" href="#lien-avec-les-conferences-et-les-visites" aria-label="Permalink to &quot;Lien avec les conférences et les visites&quot;">​</a></h2><p>Les visites servent aussi à mieux comprendre la profession.</p><p>Pendant une rencontre avec des membres du milieu, soyez attentifs à :</p><ul><li>leur parcours</li><li>les tâches qu&#39;ils décrivent</li><li>les compétences qu&#39;ils jugent importantes</li><li>la différence entre leur titre et leur travail réel</li></ul><h2 id="ce-qu-il-faut-eviter" tabindex="-1">Ce qu&#39;il faut éviter <a class="header-anchor" href="#ce-qu-il-faut-eviter" aria-label="Permalink to &quot;Ce qu&#39;il faut éviter&quot;">​</a></h2><ul><li>réduire un poste à une simple liste de technologies</li><li>croire qu&#39;un titre de poste veut toujours dire la même chose partout</li><li>oublier les attitudes et les habiletés</li></ul><h2 id="activite" tabindex="-1">Activité <a class="header-anchor" href="#activite" aria-label="Permalink to &quot;Activité&quot;">​</a></h2><p>Choisissez un <strong>poste précis</strong> lié au développement d&#39;application dans l&#39;<strong>entreprise analysée dans les activités précédentes</strong>.</p><p>Basez-vous d&#39;abord sur la <strong>section carrières</strong> de cette entreprise. Si cette section est vide ou ne donne pas assez d&#39;information, cherchez un poste semblable sur un <strong>site d&#39;emploi</strong> comme <strong>Indeed</strong>, dans une entreprise qui oeuvre dans le <strong>même secteur d&#39;activité</strong>.</p><p>À partir de ce poste, relevez :</p><ul><li>deux tâches</li><li>deux compétences techniques</li><li>deux habiletés ou attitudes importantes</li><li>une limite d&#39;intervention par rapport à un autre poste proche</li></ul>',30)])])}const h=s(a,[["render",o]]);export{m as __pageData,h as default};
